def horizontal_flip_5x5(grid):
    """Flip the inner 3x3 cells of a 5x5 grid"""
    return [row[1:4][::-1] for row in grid[1:4]]

def extract_5x5_block(grid, r_start, r_end, c_start, c_end):
    """Extract a 5x5 block from the grid"""
    return [[grid[r_start + dr][c_start + dc] for dc in range(5)] for dr in range(5)]

def place_5x5_block(grid, r_start, r_end, c_start, c_end, block):
    """Place a 5x5 block into the grid"""
    for dr in range(5):
        for dc in range(5):
            grid[r_start + dr][c_start + dc] = block[dr][dc]

def transform(grid):
    """Transform task-45984eee grid based on horizontal flip rule."""
    H, W = len(grid), len(grid[0])
    out = [[0]*W for _ in range(H)]

    sep_r = {5, 11, 17, 23}
    sep_c = {5, 11, 17}

    # Block regions (5x5 each)
    bc_ranges = [(0, 0), (0, 6), (0, 12), (0, 18)]
    br_ranges = [(0, 5), (6, 11), (12, 17), (18, 23)]

    # Find all blocks with L-shape patterns (single color, sparse)
    block_inputs = {}
    for br_idx, (br_r, br_e) in enumerate(br_ranges):
        for bc_idx, (bc_c, bc_e) in enumerate(bc_ranges):
            block_input = extract_5x5_block(grid, br_r, br_e, bc_c, bc_e)

            colors = set()
            count = 0
            for r in range(5):
                for c in range(5):
                    if block_input[r][c] != 0:
                        colors.add(block_input[r][c])
                        count += 1

            if colors and len(colors) == 1 and count in [4, 5, 6]:
                block_inputs[(br_idx, bc_idx)] = block_input

    # Load each input block's L-shape and flip it to output
    for (br_idx, bc_idx), block in block_inputs.items():
        # Output goes to: BR=bc_idx+1 (mod for orphan), BC=br_idx
        out_br = (bc_idx + 1) % 4
        out_bc = br_idx

        # Skip orphan blocks (BR3 except BC3)
        if out_br == 3 and out_bc < 3:
            continue

        flipped = horizontal_flip_5x5(block)
        place_5x5_block(out, 
                       br_ranges[out_br][0], br_ranges[out_br][1],
                       bc_ranges[out_bc][0], bc_ranges[out_bc][1],
                       flipped)

    return out

